figure.artwork:
uint32 QuicVersion;

enum {
   initial_max_stream_data(0),
   initial_max_data(1),
   initial_max_stream_id_bidi(2),
   idle_timeout(3),
   omit_connection_id(4),
   max_packet_size(5),
   stateless_reset_token(6),
   ack_delay_exponent(7),
   initial_max_stream_id_uni(8),
   (65535)
} TransportParameterId;

struct {
   TransportParameterId parameter;
   opaque value<0..2^16-1>;
} TransportParameter;

struct {
   select (Handshake.msg_type) {
      case client_hello:
         QuicVersion initial_version;

      case encrypted_extensions:
         QuicVersion negotiated_version;
         QuicVersion supported_versions<4..2^8-4>;
   };
   TransportParameter parameters<22..2^16-1>;
} TransportParameters;

section.t:
A connection that remains idle for longer than the idle timeout (see
) is closed.  A connection enters the
draining state when the idle timeout expires.
